From 7fe05be8ca3934e6f67a5f5bdbc8fdb96750e6a3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 00:52:18 +0100
Subject: [PATCH] calendar: apply event removals in DaysModel in one batch

Each removed event reset the whole model, so a calendar that replaces
many events at once rebuilt the month view per event until plasmashell
ran out of memory. Removals are now queued and applied in one reset.

BUG: 526769
---
 components/calendar/daysmodel.cpp | 72 +++++++++++++++++++++++--------
 components/calendar/daysmodel.h   |  1 +
 2 files changed, 55 insertions(+), 18 deletions(-)

diff --git a/components/calendar/daysmodel.cpp b/components/calendar/daysmodel.cpp
index 60de15b2ff..722f391c9a 100644
--- a/components/calendar/daysmodel.cpp
+++ b/components/calendar/daysmodel.cpp
@@ -13,7 +13,9 @@
 #include <QDebug>
 #include <QDir>
 #include <QMetaObject>
+#include <QSet>
 #include <algorithm>
+#include <utility>

 class DaysModelPrivate
 {
@@ -29,6 +31,10 @@ public:
     QDate lastRequestedAgendaDate;
     bool agendaNeedsUpdate = false;

+    // Event removals are collected and applied in one batch, see onEventRemoved()
+    QSet<QString> pendingRemovals;
+    bool removalsScheduled = false;
+
     // QML Ownership
     EventPluginsManager *pluginsManager = nullptr;
 };
@@ -176,6 +182,7 @@ void DaysModel::update()
     // we don't know where the old events were located.
     beginResetModel();
     d->eventsData.clear();
+    d->pendingRemovals.clear();
     d->alternateDatesData.clear();
     d->subLabelsData.clear();
     endResetModel();
@@ -194,6 +201,10 @@ void DaysModel::update()

 void DaysModel::onDataReady(const QMultiHash<QDate, CalendarEvents::EventData> &data)
 {
+    // A plugin may remove an event and add it back (e.g. when it moved), so
+    // pending removals must be applied before new data is inserted.
+    processPendingRemovals();
+
     d->eventsData.reserve(d->eventsData.size() + data.size());
     for (int i = 0; i < d->data->count(); i++) {
         const DayData &currentData = d->data->at(i);
@@ -222,6 +233,8 @@ void DaysModel::onDataReady(const QMultiHash<QDate, CalendarEvents::EventData> &

 void DaysModel::onEventModified(const CalendarEvents::EventData &data)
 {
+    processPendingRemovals();
+
     QList<QDate> updatesList;
     auto i = d->eventsData.begin();
     while (i != d->eventsData.end()) {
@@ -248,36 +261,59 @@ void DaysModel::onEventModified(const CalendarEvents::EventData &data)

 void DaysModel::onEventRemoved(const QString &uid)
 {
+    // Plugins can remove many events in one go, for example when a calendar
+    // resource reloads and replaces all of its items. Resetting the model once
+    // per event makes every view recreate all of its delegates for each removal,
+    // which can take long enough and allocate enough memory to bring the whole
+    // shell down. Collect the removals and apply them in a single batch once
+    // control returns to the event loop.
+    d->pendingRemovals.insert(uid);
+    if (!d->removalsScheduled) {
+        d->removalsScheduled = true;
+        QMetaObject::invokeMethod(this, &DaysModel::processPendingRemovals, Qt::QueuedConnection);
+    }
+}
+
+void DaysModel::processPendingRemovals()
+{
+    d->removalsScheduled = false;
+    if (d->pendingRemovals.isEmpty()) {
+        return;
+    }
+    const QSet<QString> uids = std::exchange(d->pendingRemovals, {});
+
+    QSet<QDate> updatedDates;
+    for (auto it = d->eventsData.cbegin(); it != d->eventsData.cend(); ++it) {
+        if (uids.contains(it->uid())) {
+            updatedDates.insert(it.key());
+        }
+    }
+
+    // Nothing we show is affected, so don't disturb the views
+    if (updatedDates.isEmpty()) {
+        return;
+    }
+
     // HACK We should update the model with beginRemoveRows instead of
     // using beginResetModel() since this creates a small visual glitches
     // if an event is removed in Korganizer and the calendar is open.
     // Using beginRemoveRows instead we make the code a lot more complex
     // and if not done correctly will introduce bugs.
     beginResetModel();
-    QList<QDate> updatesList;
-    auto i = d->eventsData.begin();
-    while (i != d->eventsData.end()) {
-        if (i->uid() == uid) {
-            updatesList << i.key();
-            i = d->eventsData.erase(i);
+    auto it = d->eventsData.begin();
+    while (it != d->eventsData.end()) {
+        if (uids.contains(it->uid())) {
+            it = d->eventsData.erase(it);
         } else {
-            ++i;
+            ++it;
         }
     }
+    d->agendaNeedsUpdate = true;
+    endResetModel();

-    if (!updatesList.isEmpty()) {
-        d->agendaNeedsUpdate = true;
-    }
-
-    for (const QDate date : std::as_const(updatesList)) {
-        const QModelIndex changedIndex = indexForDate(date);
-        if (changedIndex.isValid()) {
-            Q_EMIT dataChanged(changedIndex, changedIndex, {containsEventItems, containsMajorEventItems, containsMinorEventItems});
-        }
-
+    for (const QDate &date : std::as_const(updatedDates)) {
         Q_EMIT agendaUpdated(date);
     }
-    endResetModel();
 }

 void DaysModel::onAlternateCalendarDateReady(const QHash<QDate, QCalendar::YearMonthDay> &data)
diff --git a/components/calendar/daysmodel.h b/components/calendar/daysmodel.h
index 35761b7c36..aad86d4338 100644
--- a/components/calendar/daysmodel.h
+++ b/components/calendar/daysmodel.h
@@ -88,4 +88,5 @@ private:
     QModelIndex indexForDate(const QDate &date);
     bool hasMajorEventAtDate(const QDate &date) const;
     bool hasMinorEventAtDate(const QDate &date) const;
+    void processPendingRemovals();
 };
